import{_ as n,a0 as r,w as d,s as g,ao as f,I as o,x as a,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"apt-fast：飛一般的apt-get | LCTT x X-CMD","titleTemplate":false,"description":"apt-fast：飛一般的apt-get | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"apt-fast：飛一般的apt-get | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"apt-fast：飛一般的apt-get | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/apt-fast--Improve apt-get Download Speed","title":"apt-fast：飛一般的apt-get","tag":"201310","desc":""},"relativePath":"201310/apt-fast--Improve apt-get Download Speed.md","filePath":"[post].md"}'),l={name:"201310/apt-fast--Improve apt-get Download Speed.md"};function i(u,t,m,T,c,w){const p=r("Link");return d(),g("div",null,[t[11]||(t[11]=f(`<h1 id="apt-fast-飛一般的apt-get" tabindex="-1">apt-fast：飛一般的apt-get <a class="header-anchor" href="#apt-fast-飛一般的apt-get" aria-label="Permalink to “apt-fast：飛一般的apt-get”">​</a></h1><p>apt-fast是一個為 <strong>apt-get</strong> 和 <strong>aptitude</strong> 做的“ <strong>shell腳本封裝</strong> ”，通過對每個包進行併發下載的方式可以大大減少APT的下載時間。apt-fast使用aria2c或axel下載管理器來減少APT下載時間。就像傳統的apt-get包管理器一樣，apt-fast支持幾乎所有的apt-get功能，如， <strong>install</strong> , <strong>remove</strong> , <strong>update</strong> , <strong>upgrade</strong> , <strong>dist-upgrade</strong> 等等，並且更重要的是它也支持proxy。</p><p>###在Ubuntu上安裝apt-fast</p><p>使用以下PPA去安裝apt-fast。apt-fast開發者説：“ <strong>一些發行版，如PCLinux已經在他們默認的倉庫中包括了apt-fast</strong> 。” 我希望它將來也包含在Ubuntu/Debian的默認倉庫中。</p><p>添加apt-fast的PPA，在終端中輸入以下命令。</p><pre><code>sudo add-apt-repository ppa:apt-fast/stable
</code></pre><p>用命令更新源：</p><pre><code>sudo apt-get update
</code></pre><p>使用命令安裝apt-fast：</p><pre><code>sudo apt-get install apt-fast
</code></pre><p>在安裝期間，它將要求你輸入下載包的最大鏈接數。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/sk@sk-_003.png" alt=""></p><p>在下一個對話框裏面，會問你是否要禁止apt-fast的確認對話框。選擇No並繼續安裝。如果你選擇Yes，apt-fast在安裝軟件包時不會問你確認與否。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/sk@sk-_0041.png" alt=""></p><p>我發現 <strong>aria2</strong> 下載管理器已經隨着apt-fast的安裝而自動安裝。所以，你不必單獨安裝aria2。</p><p>如果你想重新配置apt-fast選項，你可以使用命令：</p><pre><code>sudo dpkg-reconfigure apt-fast
</code></pre><p>###用法</p><p>與apt-get功能相似，我們可以使用：</p><pre><code>apt-fast install package

apt-fast remove package

apt-fast update

apt-fast upgrade

apt-fast dist-upgrade
</code></pre><p>及更多命令。</p><p>工作中的apt-fast包管理器：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/sk@sk-_0051.png" alt=""></p><p>###創建別名（可選）</p><p>編輯 <strong>~/.bashrc</strong> 文件在末尾添加下面這行。</p><pre><code>alias apt-get=&#39;apt-fast&#39;
</code></pre><p>或者簡單運行以下命令在你的 <strong>~/.bashrc</strong> 中添加它。</p><pre><code>sudo echo &quot;alias apt-get=&#39;apt-fast&#39;&quot; &gt;&gt; ~/.bashrc
</code></pre><p>從現在每當你運行apt-get命令去移除，更新和升級包時，它將在後台自動使用apt-fast。聽起來很酷吧？</p><p>在測試期間，當下載包時我發現它與apt-get相比非常快。試一試，你一定會贊同我的看法。感謝閲讀！！</p><hr>`,31)),o("p",null,[t[1]||(t[1]=a("via: ",-1)),e(p,{href:"http://www.unixmen.com/improve-apt-get-download-speed-apt-fast/"},{default:s(()=>[...t[0]||(t[0]=[a("http://www.unixmen.com/improve-apt-get-download-speed-apt-fast/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=a("譯者：",-1)),e(p,{href:"https://github.com/Vito"},{default:s(()=>[...t[2]||(t[2]=[a("Vito",-1)])]),_:1}),t[5]||(t[5]=a(" 校對：",-1)),e(p,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[3]||(t[3]=[a("Caroline",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=a("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[a("LCTT",-1)])]),_:1}),t[9]||(t[9]=a(" 原創翻譯，",-1)),e(p,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[a("Linux中國",-1)])]),_:1}),t[10]||(t[10]=a(" 榮譽推出",-1))])])}const P=n(l,[["render",i]]);export{k as __pageData,P as default};
